from __future__ import absolute_import
from taf.selenium.sc.pages.view import ViewPanel
from taf.selenium.sc.pages.navigatable_page import NavigatablePage
from taf.selenium.sc.common.utils import wait_for_operation_success


class Software(object):
    def __init__(self, driver):
        self._software = SoftwarePage(driver)

    @property
    def software(self):
        return self._software


class SoftwarePage(NavigatablePage):
    _MENU_ROUTE_LIST = ["software"]

    def __init__(self, driver):
        super(SoftwarePage, self).__init__(driver)
        self._view_panel = SoftwareViewPanel(driver)

    def _get_route_list(self):
        return self._MENU_ROUTE_LIST

    def get_active_and_passive_info(self, timeout=60):
        return self._view_panel.get_active_and_passive_info(timeout)


class SoftwareViewPanel(ViewPanel):
    _ACTIVE_SOFTWARE_INFO = '//*[@id="active-software-info"]'
    _PASSIVE_SOFTWARE_INFO = '//*[@id="passive-software-info"]'
    _SOFTWARE_TYPE = '//span[@class="software-type"]'

    _SOFTWARE_ENTRY = '//*[contains(@class, "software-info-entry")]'
    _SOFTWARE_TITLE = '//span[@class="entry-title"]'
    _SOFTWARE_TEXT = '//span[@class="entry-text"]'

    def __init__(self, driver):
        super(SoftwareViewPanel, self).__init__(driver)

    @wait_for_operation_success(5)
    def _get_value_by_xpath(self, title_xpath):
        return self.driver.find_element_by_xpath(title_xpath).text.strip(':')

    @wait_for_operation_success(5)
    def _get_software_type(self, sft_type, timeout=5):
        if sft_type == 'active':
            sft_info_xpath = self._ACTIVE_SOFTWARE_INFO
        else:
            sft_info_xpath = self._PASSIVE_SOFTWARE_INFO
        sft_type_xpath = sft_info_xpath + self._SOFTWARE_TYPE
        return self.get_text_by_xpath(sft_type_xpath, timeout).strip(':')

    @wait_for_operation_success(5)
    def _get_software_info(self, sft_type, value_type, timeout=5):
        if sft_type == 'active':
            sft_root_xpath = self._ACTIVE_SOFTWARE_INFO
        else:
            sft_root_xpath = self._PASSIVE_SOFTWARE_INFO

        if value_type == 'key':
            value_xpath = self._SOFTWARE_TITLE
        else:
            value_xpath = self._SOFTWARE_TEXT

        values_xpath = [xpath + value_xpath for xpath in
                        self.get_elements_xpath_list(sft_root_xpath + self._SOFTWARE_ENTRY, timeout)]

        values = []
        for value_xpath in values_xpath:
            values.append(self._get_value_by_xpath(value_xpath))
        return values

    def get_active_and_passive_info(self, timeout=5):
        active_sft_type = self._get_software_type('active')
        active_sft_key = self._get_software_info(sft_type='active', value_type='key', timeout=timeout)
        active_sft_value = self._get_software_info(sft_type='active', value_type='value', timeout=timeout)
        active = {active_sft_type: dict(zip(active_sft_key, active_sft_value))}

        passive_sft_type = self._get_software_type('passive')
        passive_sft_key = self._get_software_info(sft_type='passive', value_type='key', timeout=timeout)
        passive_sft_value = self._get_software_info(sft_type='passive', value_type='value', timeout=timeout)
        passive = {passive_sft_type: dict(zip(passive_sft_key, passive_sft_value))}

        active.update(passive)
        return active
